"""Shared local-web dashboard shell for the portfolio prototypes."""
import json
import os
import threading
import webbrowser
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


CSS = r"""
:root{--nav:#152938;--nav2:#203b4d;--accent:#2f607c;--bg:#f3f5f7;--line:#dce2e7;--muted:#65758b;--ink:#071529;--good:#18794e;--warn:#b7791f;--bad:#c53030}
*{box-sizing:border-box}body{margin:0;font-family:Inter,"Segoe UI",Arial,sans-serif;color:var(--ink);background:var(--bg)}
.layout{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{position:fixed;inset:0 auto 0 0;width:240px;background:var(--nav);color:#fff;padding:26px 18px;display:flex;flex-direction:column}.brand{display:flex;gap:12px;align-items:center;margin-bottom:38px}.logo{width:42px;height:42px;border-radius:12px;background:#376b88;display:grid;place-items:center;font-weight:800}.brand b{display:block}.brand small{color:#a9c3d4}.nav{display:grid;gap:9px}.nav button{width:100%;border:0;background:transparent;text-align:left;font:inherit;padding:13px 14px;border-radius:9px;color:#bcd0dc;cursor:pointer}.nav button:hover{background:#203746;color:white}.nav button.active{background:#2a4050;color:white}.nav span{display:inline-block;width:25px}.user{margin-top:auto;border-top:1px solid #314655;padding-top:20px;display:flex;gap:11px;align-items:center}.avatar{width:36px;height:36px;border-radius:50%;background:#376b88;display:grid;place-items:center;font-weight:800}.user small{display:block;color:#a9c3d4}.main{grid-column:2}.topbar{height:92px;background:white;border-bottom:1px solid var(--line);padding:23px 34px;display:flex;justify-content:space-between;align-items:center}.topbar h1{font-size:24px;margin:0 0 5px}.topbar p{margin:0;color:var(--muted);font-size:14px}.content{padding:28px 34px}.app-view{display:none}.app-view.active{display:block}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-bottom:18px}.card,.panel{background:white;border:1px solid var(--line);border-radius:13px;padding:21px}.card label{display:block;color:var(--muted);font-size:13px;margin-bottom:14px}.metric{font-size:27px;font-weight:800}.hint{color:var(--muted);font-size:12px;margin-top:9px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}.panel h2{font-size:17px;margin:0 0 4px}.panel .sub{color:var(--muted);font-size:13px;margin-bottom:22px}.btn{border:0;background:var(--accent);color:white;border-radius:9px;padding:12px 17px;font-weight:650;cursor:pointer}.btn:hover{filter:brightness(.92)}.btn.secondary{background:#eaf0f4;color:#21465d}.toolbar{display:flex;gap:10px;align-items:center}.field{width:100%;border:1px solid #cdd6dd;border-radius:8px;padding:11px;background:white}textarea.field{min-height:115px;resize:vertical}.progress-row{display:grid;grid-template-columns:170px 1fr 90px;gap:12px;align-items:center;margin:17px 0;font-size:13px}.track{height:10px;background:#e8edf0;border-radius:99px;overflow:hidden}.fill{height:100%;background:var(--accent);border-radius:99px}.list{display:grid}.list-item{padding:14px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:15px}.list-item b{font-size:14px}.list-item small{display:block;color:var(--muted);margin-top:5px}.pill{display:inline-block;border-radius:99px;padding:4px 9px;font-size:11px;font-weight:700}.good{background:#e6f5ed;color:var(--good)}.warn{background:#fff4d6;color:#8b5b00}.bad{background:#fde8e8;color:var(--bad)}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:var(--muted);font-weight:600;padding:11px;border-bottom:1px solid var(--line)}td{padding:12px 11px;border-bottom:1px solid #edf0f2}.empty{text-align:center;color:var(--muted);padding:42px}.loading{opacity:.55;pointer-events:none}.notice{padding:12px 14px;border-radius:9px;background:#eaf3f8;color:#264f68;font-size:13px;margin-bottom:16px}.error{background:#fde8e8;color:#9b2424}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.setting{display:flex;justify-content:space-between;align-items:center;padding:16px 0;border-bottom:1px solid var(--line)}body.compact .card,body.compact .panel{padding:15px}body.compact td{padding:8px}
@media(max-width:1000px){.layout{grid-template-columns:78px 1fr}.sidebar{width:78px;padding:22px 12px}.brand div:last-child,.nav button{font-size:0}.nav button span{font-size:16px}.user div:last-child{display:none}.cards{grid-template-columns:repeat(2,1fr)}.grid,.settings-grid{grid-template-columns:1fr}.main{grid-column:2}.progress-row{grid-template-columns:120px 1fr 75px}}
"""


def shell(title, subtitle, initials, body, action="Executar analise"):
    return f"""<!doctype html><html lang='pt'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>{title}</title><style>{CSS}</style></head>
<body><div class='layout'><aside class='sidebar'><div class='brand'><div class='logo'>{initials}</div><div><b>{title}</b><small>Python portfolio</small></div></div><nav class='nav'><button type='button' class='active' data-view='dashboard'><span>⌂</span> Dashboard</button><button type='button' data-view='data'><span>▦</span> Dados</button><button type='button' data-view='reports'><span>▤</span> Relatórios</button><button type='button' data-view='settings'><span>⚙</span> Definições</button></nav><div class='user'><div class='avatar'>DU</div><div><b>Demo User</b><small>Portfolio mode</small></div></div></aside>
<main class='main'><header class='topbar'><div><h1 id='pageTitle'>{title}</h1><p id='pageSubtitle'>{subtitle}</p></div><button class='btn' id='primaryAction'>{action}</button></header><section class='content'>
<div class='app-view active' id='view-dashboard'>{body}</div>
<div class='app-view' id='view-data'><div class='cards'><div class='card'><label>Fonte ativa</label><div class='metric' style='font-size:17px' id='dataSource'>Local</div><div class='hint'>Dados processados neste computador</div></div><div class='card'><label>Indicadores disponíveis</label><div class='metric' id='indicatorCount'>-</div><div class='hint'>Métricas no dashboard</div></div><div class='card'><label>Última atualização</label><div class='metric' style='font-size:17px' id='lastUpdate'>Agora</div><div class='hint'>Sessão atual</div></div><div class='card'><label>Estado</label><div class='metric' style='font-size:17px;color:var(--good)'>Operacional</div><div class='hint'>Processamento local</div></div></div><div class='panel'><h2>Resumo dos dados</h2><div class='sub'>Valores atualmente apresentados pela aplicação</div><table><thead><tr><th>Indicador</th><th>Valor atual</th><th>Interpretação</th></tr></thead><tbody id='dataSummary'></tbody></table></div></div>
<div class='app-view' id='view-reports'><div id='reportCards'></div><div class='grid'><div class='panel'><h2>Relatório executivo</h2><div class='sub'>Síntese pronta para apresentação</div><div id='executiveSummary' class='list'></div></div><div class='panel'><h2>Leitura recomendada</h2><div class='sub'>Como apresentar estes resultados</div><div class='notice'>Começa pelos indicadores principais, explica os desvios ou riscos e termina com a ação recomendada.</div><button class='btn secondary' type='button' onclick='window.print()'>Imprimir relatório</button></div></div></div>
<div class='app-view' id='view-settings'><div class='settings-grid'><div class='panel'><h2>Preferências de visualização</h2><div class='sub'>Guardadas apenas neste navegador</div><div class='setting'><div><b>Modo compacto</b><small>Reduz o espaçamento das tabelas e cartões</small></div><input id='compactMode' type='checkbox'></div><div class='setting'><div><b>Executar ao abrir</b><small>Atualiza os resultados automaticamente</small></div><input id='autoRun' type='checkbox' checked></div><button class='btn' id='saveSettings' type='button' style='margin-top:18px'>Guardar definições</button></div><div class='panel'><h2>Sobre a aplicação</h2><div class='sub'>Informação técnica</div><div class='list'><div class='list-item'><div><b>Execução</b><small>Servidor local Python, sem envio para serviços externos.</small></div><span class='pill good'>Local</span></div><div class='list-item'><div><b>Interface</b><small>Dashboard responsivo para demonstrações e entrevistas.</small></div><span class='pill good'>Ativa</span></div><div class='list-item'><div><b>Privacidade</b><small>Os ficheiros permanecem no computador.</small></div><span class='pill good'>Protegida</span></div></div></div></div></div>
</section></main></div><script>
const viewMeta={{dashboard:['{title}','{subtitle}'],data:['Dados','Fontes, indicadores e estado do processamento'],reports:['Relatórios','Resumo executivo dos resultados atuais'],settings:['Definições','Preferências e informação da aplicação']}};
function syncSecondaryViews(){{let cards=[...document.querySelectorAll('#view-dashboard .card')],source=document.querySelector('#view-dashboard #source');document.getElementById('dataSource').textContent=source?source.value.split(/[\\/]/).pop():'Base de dados local';document.getElementById('indicatorCount').textContent=cards.length;document.getElementById('lastUpdate').textContent=new Date().toLocaleTimeString('pt-PT',{{hour:'2-digit',minute:'2-digit'}});let items=cards.map(c=>({{label:c.querySelector('label')?.textContent||'Indicador',value:c.querySelector('.metric')?.textContent||'-',hint:c.querySelector('.hint')?.textContent||''}}));document.getElementById('dataSummary').innerHTML=items.map(x=>`<tr><td><b>${{x.label}}</b></td><td>${{x.value}}</td><td>${{x.hint}}</td></tr>`).join('');document.getElementById('reportCards').className='cards';document.getElementById('reportCards').innerHTML=cards.map(c=>c.outerHTML).join('');document.getElementById('executiveSummary').innerHTML=items.map(x=>`<div class='list-item'><div><b>${{x.label}}</b><small>${{x.hint}}</small></div><strong>${{x.value}}</strong></div>`).join('')}}
document.querySelectorAll('.nav button').forEach(btn=>btn.addEventListener('click',()=>{{document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.app-view').forEach(x=>x.classList.remove('active'));document.getElementById('view-'+btn.dataset.view).classList.add('active');let m=viewMeta[btn.dataset.view];pageTitle.textContent=m[0];pageSubtitle.textContent=m[1];primaryAction.style.display=btn.dataset.view==='dashboard'?'':'none';if(btn.dataset.view!=='dashboard')syncSecondaryViews();}}));
let saved=JSON.parse(localStorage.getItem('{initials}-settings')||'{{}}');compactMode.checked=!!saved.compact;autoRun.checked=saved.autoRun!==false;document.body.classList.toggle('compact',compactMode.checked);saveSettings.onclick=()=>{{let value={{compact:compactMode.checked,autoRun:autoRun.checked}};localStorage.setItem('{initials}-settings',JSON.stringify(value));document.body.classList.toggle('compact',value.compact);saveSettings.textContent='Definições guardadas';setTimeout(()=>saveSettings.textContent='Guardar definições',1400)}};
</script></body></html>"""


def serve_dashboard(html, action, port):
    """Serve a dashboard and one JSON POST action, then open it in the browser."""
    class Handler(BaseHTTPRequestHandler):
        def reply(self, status, content, content_type="application/json"):
            raw = content if isinstance(content, bytes) else content.encode("utf-8")
            self.send_response(status); self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(raw))); self.end_headers(); self.wfile.write(raw)
        def do_GET(self):
            self.reply(200, html, "text/html; charset=utf-8") if self.path == "/" else self.reply(404, json.dumps({"error":"not found"}))
        def do_POST(self):
            if self.path != "/api/run": return self.reply(404, json.dumps({"error":"not found"}))
            try:
                size=int(self.headers.get("Content-Length","0")); payload=json.loads(self.rfile.read(size) or b"{}")
                self.reply(200, json.dumps(action(payload)))
            except Exception as exc: self.reply(400, json.dumps({"error":str(exc)}))
        def log_message(self, *_): pass
    server=ThreadingHTTPServer(("127.0.0.1",port),Handler); url=f"http://localhost:{server.server_port}"
    print(f"Visual dashboard: {url}")
    if not os.environ.get("PORTFOLIO_NO_BROWSER"): threading.Timer(.6,lambda:webbrowser.open(url)).start()
    server.serve_forever()
